'use client';

import { Bookmark } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

export interface BookmarkletLinkProps {
  /** The `javascript:` URL generated by `buildBookmarklet` (our own, trusted code). */
  code: string;
  label: string;
}

/**
 * Draggable bookmarklet link. React 19 refuses to render `javascript:` URLs in `href`,
 * so the href is set on the DOM node after mount. The code is generated server-side by
 * git-moxfield itself; nothing user-controlled is ever placed in it. Clicking the link
 * here does nothing except explain that it must be dragged to the bookmarks bar.
 */
export function BookmarkletLink({ code, label }: BookmarkletLinkProps) {
  const link = useRef<HTMLAnchorElement>(null);
  const [hint, setHint] = useState(false);

  useEffect(() => {
    link.current?.setAttribute('href', code);
  }, [code]);

  return (
    <span className="inline-flex flex-col items-start gap-1.5">
      <a
        ref={link}
        draggable
        className="inline-flex h-11 cursor-grab items-center gap-2 rounded-full border border-accent/40 bg-accent-soft px-4 text-sm font-semibold text-accent shadow-card select-none active:cursor-grabbing"
        title="Drag this to your bookmarks bar"
        onClick={(event) => {
          event.preventDefault();
          setHint(true);
        }}
      >
        <Bookmark aria-hidden="true" className="size-4" />
        {label}
      </a>
      <span role="status" className="text-xs text-muted">
        {hint
          ? 'Drag the button to your bookmarks bar; it only works on a Moxfield deck page.'
          : 'Drag to your bookmarks bar'}
      </span>
    </span>
  );
}
